    pub async fn search_events(
        &self,
        calendar_id: i64,
        from: &str,
        to: &str,
    ) -> Result<Vec<EventInfo>, InternalError> {
        let mut url = self
            .api_base
            .join(&format!("internal/mcp/events/{}/search", calendar_id))
            .map_err(|e| InternalError::Connection(format!("failed to join URL: {}", e)))?;
        url.query_pairs_mut()
            .append_pair("from", from)
