    State(state): State<AppState>,
    headers: HeaderMap,
    axum::extract::Path(intent_id): axum::extract::Path<String>,
) -> Response {
    if !check_internal_key(&headers, &state.bridge_key) {
        return (StatusCode::UNAUTHORIZED, "unauthorized").into_response();
