            if intent.expires_at <= now {
                (
                    StatusCode::NOT_FOUND,
                    Json(serde_json::json!({"error": "delete_intent_expired"})),
                )
                    .into_response()
            } else {
                (
                    StatusCode::OK,
                    Json(serde_json::json!({ "delete_intent": intent })),
                )
                    .into_response()
            }
        }
        None => (
            StatusCode::NOT_FOUND,
